def roofline(k):
    fig, ax = plt.subplots(figsize=(4.3, 2.7))
    R = 295.0
    xs = np.logspace(-0.3, 4, 300)
    roof = np.minimum(1.0, xs / R)
    ax.plot(xs[xs <= R], roof[xs <= R], color=C['memory'], lw=3)
    ax.plot(xs[xs >= R], roof[xs >= R], color=C['compute'], lw=3)
    ax.fill_between(xs[xs <= R], 0.001, roof[xs <= R], color=C['memory_l'], alpha=0.6)
    ax.fill_between(xs[xs >= R], 0.001, roof[xs >= R], color=C['compute_l'], alpha=0.6)
    ax.axvline(R, color=C['neutral'], lw=1, ls='--')
    ax.text(R * 1.1, 0.0045, 'ridge 295\n(H100 FP16,\nderived)', color=C['neutral'], fontsize=10)
    pts = [('decode, B = 1', 1.0, 'memory', (10, -16), 'left'), ('decode, B = 80', 80.0, 'memory', (-10, 8), 'right'), ('prefill,\n1,024-token\nprompt', 1024.0, 'compute', None, 'left')]
    for i, (lab, x, ck, off, ha) in enumerate(pts[:k]):
        y = min(1.0, x / R)
        ax.plot([x], [y], 'o', ms=11, color=C[ck], mec='white', mew=1.5, zorder=5)
        if off is None:
            ax.annotate(lab, (x, y), xytext=(R * 1.35, 0.2), textcoords='data', ha=ha, va='center', fontsize=11.5, fontweight='bold', color=C[ck], linespacing=1.0, arrowprops=dict(arrowstyle='-', color=C[ck], lw=1.2, shrinkA=2, shrinkB=6))
            continue
        ax.annotate(lab, (x, y), xytext=off, textcoords='offset points', ha=ha, fontsize=11.5, fontweight='bold', color=C[ck])
    ax.set_xscale('log')
    ax.set_yscale('log')
    ax.set_xlim(0.5, 20000.0)
    ax.set_ylim(0.001, 3)
    ax.minorticks_off()
    ax.set_xticks([1, 10, 100, 1000])
    ax.set_xticklabels(['1', '10', '100', '1,000'])
    ax.set_yticks([])
    ax.set_xlabel('FLOP per byte of FP16 weights')
    ax.set_ylabel('Attained rate (schematic)')
    sp.save(fig, out / f'roofline_step{k}.svg')
for k in (1, 2, 3):
    roofline(k)

def chunk(k):
    fig, ax = plt.subplots(figsize=(5.8, 2.4))

    def row(y, label, segs):
        ax.text(-0.3, y + 0.3, label, ha='right', va='center', fontsize=11, fontweight='bold')
        for x0, w, ck in segs:
            ax.add_patch(Rectangle((x0, y), w, 0.6, color=C[ck], ec='white', lw=0.8))
    segs = [(0, 1, 'memory'), (1, 1, 'memory'), (2, 8, 'compute')] + [(10 + i, 1, 'memory') for i in range(6)]
    row(1.3, 'Whole\nprompt', segs)
    ax.text(6, 1.6, '10,000-token prefill', ha='center', va='center', color='white', fontsize=11, fontweight='bold')
    ax.annotate('', xy=(10, 2.15), xytext=(2, 2.15), arrowprops=dict(arrowstyle='<->', color=C['danger'], lw=1.4))
    ax.text(6, 2.3, 'every active stream waits', ha='center', fontsize=10.5, color=C['danger'], fontweight='bold')
