        segs = [(0, 1, 'memory'), (1, 1, 'memory')]
        x = 2
        for i in range(10):
            segs.append((x, 0.45, 'memory'))
            segs.append((x + 0.45, 0.95, 'compute'))
            x += 1.4
        row(0.0, '512-token\nchunks', segs)
