PARTS = [('GEMM', 'compute'), ('attention', 'memory'), ('element-wise', 'data'), ('AllReduce', 'network'), ('launch', 'neutral')]
COLS = [('Baseline', [34.0, 20.4, 10.2, 10.2, 10.2], 'budget_base1'), ('INT4 weights', [18.7, 20.4, 10.2, 10.2, 10.2], 'budget_prec'), ('+ fusion, replay', [18.7, 15.3, 3.4, 10.2, 2.0], 'budget_fused')]
TARGET = 50.0

def budget(k):
    fig, ax = plt.subplots(figsize=(5.8, 2.6))
    n = min(k, 3)
    for i, (lab, vals, key) in enumerate(COLS):
        y = 2 - i
        left = 0
        a = 1.0 if i < n else 0.0
        for (pname, ck), v in zip(PARTS, vals):
            ax.barh(y, v, left=left, color=C[ck], height=0.6, alpha=a, ec='white', lw=0.6)
            left += v
        ax.text(-1, y, lab, ha='right', va='center', fontsize=11.5, fontweight='bold', alpha=a)
        ax.text(left + 1, y, f"{ {'Baseline': '85.0', 'INT4 weights': '69.7', '+ fusion, replay': '49.6'}[lab]} ms", va='center', fontsize=12, fontweight='bold', alpha=a, color=C['danger'] if {'Baseline': 85.0, 'INT4 weights': 69.7, '+ fusion, replay': 49.6}[lab] > TARGET else C['data'])
    for (pname, ck), xk in zip(PARTS, (0, 14, 28.5, 57, 79)):
        ax.text(xk, 2.62, pname, fontsize=10, color=C[ck], fontweight='bold')
    ax.axvline(TARGET, color=C['danger'], ls='--', lw=1.8)
    ax.text(TARGET + 0.8, -2.3, '50 ms target', color=C['danger'], fontsize=10.5, fontweight='bold')
    if k >= 4:
        ax.barh(-1, 15.2, color=C['data'], height=0.6)
        ax.text(52, -0.85, '15.2 ms per token on average,', va='center', fontsize=11, fontweight='bold', color=C['data'])
        ax.text(52, -1.4, 'but blocks arrive 53.6 ms apart', va='center', fontsize=11, fontweight='bold', color=C['danger'])
        ax.text(-1, -1, 'Speculate', ha='right', va='center', fontsize=11.5, fontweight='bold')
    ax.set_xlim(0, 100)
    ax.set_ylim(-2.6, 3.0)
    ax.set_yticks([])
    ax.spines['left'].set_visible(False)
    ax.set_xlabel('ms per batch-one decode step, 70B on 8× H100 (constructed)')
    sp.save(fig, out / f'budget_step{k}.svg')
for k in (1, 2, 3, 4):
    budget(k)
