def fanout():
    fig, ax = plt.subplots(figsize=(5.8, 2.3))
    leaves = 100
    N = np.logspace(0, 3, 200)
    q1 = 1 - 0.99
    tiers = ((q1, 'leaf slow {}% (p{})', 'danger', (85, 4, 'right')), (q1 / 10, '{}% (p{})', 'compute', (118, 8, 'left')), (q1 / 100, '{}% (p{})', 'data', (118, -9, 'left')))
    for q, lab, ck, (dx, dy, ha) in tiers:
        p = [1 - calc_all_up_availability(1 - q, n) for n in N]
        ax.plot(N, 100 * np.array(p), color=C[ck], lw=2.6)
        v = 100 * (1 - {4: 0.3660323413, 8: 0.9047921471, -9: 0.9900493387}[dy])
        ax.plot([leaves], [v], 'o', ms=8, color=C[ck], mec='white', zorder=5)
        ax.text(1150, 100 * p[-1], lab.format(f'{100 * q:g}', f'{100 - 100 * q:g}'), fontsize=10.5, color=C[ck], fontweight='bold', va='center')
        ax.text(dx, v + dy, f'{v:.0f}%' if v >= 5 else f'{v:.1f}%', fontsize=11, color=C[ck], fontweight='bold', ha=ha)
    ax.axvline(leaves, color=C['neutral'], ls='--', lw=1)
    ax.set_xscale('log')
    ax.set_xlim(1, 1000)
    ax.set_xticks([1, 10, 100, 1000])
    ax.set_xticklabels(['1', '10', '100', '1,000'])
    ax.minorticks_off()
    ax.set_ylim(-12, 105)
    ax.set_xlabel('Leaves one request waits for (N)')
    ax.set_ylabel('Requests slow (%)')
    sp.save(fig, out / 'fanout.svg')
fanout()

